'use strict';
// Small transparent drawing workspace for reusable everyday objects.
$('propsTab').insertAdjacentHTML('beforeend','<details open><summary>Your object library</summary><div class="row"><button id="drawObject">＋ Draw object</button><button id="saveObject">Save selection</button></div><div id="objectLibrary" class="asset-library"></div></details>');
document.body.insertAdjacentHTML('beforeend',`<dialog id="drawingDialog"><div class="drawing-heading"><div><div class="eyebrow">OBJECT WORKSHOP</div><h2>Draw something for your story.</h2></div><button id="closeDrawing">Close</button></div><div class="drawing-tools"><label>Ink <input id="brushColor" type="color" value="#31564d"></label><label>Size <input id="brushSize" type="range" min="2" max="48" value="10"></label><label><input id="eraser" type="checkbox"> Eraser</label><button id="undoStroke">Undo stroke</button><button id="clearDrawing">Clear</button></div><canvas id="drawingCanvas" width="800" height="500" aria-label="Drawing canvas"></canvas><div class="drawing-tools"><label>Name <input id="drawingName" value="My object" maxlength="60"></label><span class="note">Transparent background · saved in your object library</span><button id="addDrawing" class="primary">Save & add to scene</button></div></dialog>`);
let strokes=[],activeStroke=null;
const dc=$('drawingCanvas'),dctx=dc.getContext('2d');
function renderDrawing(){dctx.clearRect(0,0,dc.width,dc.height);dctx.lineCap='round';dctx.lineJoin='round';for(const s of strokes){dctx.globalCompositeOperation=s.erase?'destination-out':'source-over';dctx.strokeStyle=s.color;dctx.fillStyle=s.color;dctx.lineWidth=s.size;dctx.beginPath();dctx.moveTo(s.points[0].x,s.points[0].y);for(const p of s.points.slice(1))dctx.lineTo(p.x,p.y);if(s.points.length===1){dctx.arc(s.points[0].x,s.points[0].y,s.size/2,0,Math.PI*2);dctx.fill()}else dctx.stroke()}dctx.globalCompositeOperation='source-over'}
function drawingPoint(e){const r=dc.getBoundingClientRect();return{x:(e.clientX-r.left)*dc.width/r.width,y:(e.clientY-r.top)*dc.height/r.height}}
dc.onpointerdown=e=>{activeStroke={color:$('brushColor').value,size:+$('brushSize').value,erase:$('eraser').checked,points:[drawingPoint(e)]};strokes.push(activeStroke);dc.setPointerCapture(e.pointerId);renderDrawing()};dc.onpointermove=e=>{if(!activeStroke)return;activeStroke.points.push(drawingPoint(e));renderDrawing()};dc.onpointerup=dc.onpointercancel=()=>activeStroke=null;
$('drawObject').onclick=()=>{stop();strokes=[];renderDrawing();$('drawingDialog').showModal()};$('closeDrawing').onclick=()=>$('drawingDialog').close();$('undoStroke').onclick=()=>{strokes.pop();renderDrawing()};$('clearDrawing').onclick=()=>{strokes=[];renderDrawing()};
async function assetRecords(mode,operation){const db=await database();return new Promise((resolve,reject)=>{const tx=db.transaction('workspace',mode),request=operation(tx.objectStore('workspace'));let result;request.onsuccess=()=>result=request.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error)})}
async function saveAsset(asset){const list=await assetRecords('readonly',s=>s.get('assets'))||[];list.push(asset);await assetRecords('readwrite',s=>s.put(list,'assets'));await renderAssets()}
async function renderAssets(){try{const list=await assetRecords('readonly',s=>s.get('assets'))||[];const el=$('objectLibrary');el.replaceChildren();for(const asset of list){const card=document.createElement('div');const b=document.createElement('button');b.className='asset-card';const image=document.createElement('img');image.src=asset.src;image.alt=asset.name;const label=document.createElement('span');label.textContent=asset.name;b.append(image,label);b.onclick=()=>newObject('image',{src:asset.src,name:asset.name,...(asset.explainerAsset?{explainerAsset:structuredClone(asset.explainerAsset),...(asset.objectAnimation?{objectAnimation:structuredClone(asset.objectAnimation)}:{})}:{})});const remove=document.createElement('button');remove.textContent='Remove';remove.className='editcast';remove.onclick=async()=>{const current=await assetRecords('readonly',s=>s.get('assets'))||[];await assetRecords('readwrite',s=>s.put(current.filter(a=>a.id!==asset.id),'assets'));renderAssets()};card.append(b,remove);el.append(card)}if(!list.length)el.innerHTML='<p class="note">Draw an object or save an imported image to reuse it in other projects.</p>'}catch{toast('Could not load your object library.')}}
$('addDrawing').onclick=async()=>{if(!strokes.some(s=>!s.erase))return toast('Draw an object first.');const src=dc.toDataURL('image/png'),name=$('drawingName').value.trim()||'My object';try{await saveAsset({id:uid(),name,src});newObject('image',{src,name});$('drawingDialog').close();toast('Drawing added to your scene and object library.')}catch{toast('Could not save the drawing.')}};
$('saveObject').onclick=async()=>{const o=object();if(o?.type!=='image')return toast('Select an imported image or drawing to save it.');try{await saveAsset({id:uid(),name:o.name,src:o.src,...(o.explainerAsset?{explainerAsset:structuredClone(o.explainerAsset),...(o.objectAnimation?{objectAnimation:structuredClone(o.objectAnimation)}:{})}:{})});toast('Saved to your reusable object library.')}catch{toast('Could not save this object.')}};
renderAssets();
